package lol.simeon.husk.protocol.packet

import lol.simeon.husk.protocol.ClientboundPacket
import lol.simeon.husk.protocol.PacketMapping
import lol.simeon.husk.protocol.ServerboundPacket
import lol.simeon.husk.protocol.StateRegistry
import lol.simeon.husk.protocol.clientbound
import lol.simeon.mycelium.ByteMessage
import lol.simeon.mycelium.NamespacedKey
import lol.simeon.mycelium.Version
import net.kyori.adventure.nbt.CompoundBinaryTag
import net.kyori.adventure.text.Component

// Configuration phase exists only 1.20.2+ (protocol 764+). IDs are generated by
// tools/generate-packet-ids.sh (1.20.2–26.3).

class FinishConfigurationPacket : ClientboundPacket {
    override fun encode(buf: ByteMessage, version: Version) = Unit // no fields
}

class ConfigDisconnectPacket(val reason: Component) : ClientboundPacket {
    override fun encode(buf: ByteMessage, version: Version) = buf.writeComponent(reason, version)
}

class ConfigKeepAlivePacket(val id: Long) : ClientboundPacket {
    override fun encode(buf: ByteMessage, version: Version) {
        buf.buf.writeLong(id)
    }
}

class ConfigPluginMessagePacket(val channel: NamespacedKey, val data: ByteArray) : ClientboundPacket {
    override fun encode(buf: ByteMessage, version: Version) {
        buf.writeNamespacedKey(channel)
        buf.buf.writeBytes(data)
    }
}

/**
 * One registry's data (1.20.2+): registry id + entries, each an identifier and an optional nameless
 * NBT compound. Sent during CONFIGURATION so the client can build its registries before PLAY.
 */
class RegistryDataPacket(
    val registryId: String,
    val entries: List<Entry>,
) : ClientboundPacket {
    class Entry(val key: String, val data: CompoundBinaryTag?)

    override fun encode(buf: ByteMessage, version: Version) {
        buf.writeString(registryId)
        buf.writeList(entries) { entry ->
            buf.writeString(entry.key)
            buf.writeOptional(entry.data) { buf.writeCompoundTag(it, version) }
        }
    }
}

/** Registry Data as sent by 1.20.2–1.20.4: the whole registry [codec] as one nameless NBT compound. */
class CodecRegistryDataPacket(val codec: CompoundBinaryTag) : ClientboundPacket {
    override fun encode(buf: ByteMessage, version: Version) = buf.writeCompoundTag(codec, version)
}

/**
 * Update Tags (1.20.5+ configuration form): per registry, a set of tags mapping a tag id to the
 * registry entry indices it covers. The client validates its built-in tag references against this.
 */
class UpdateTagsPacket(val registries: List<TagRegistry>) : ClientboundPacket {
    class TagRegistry(val registryId: String, val tags: List<Tag>)
    class Tag(val name: String, val entryIds: IntArray)

    override fun encode(buf: ByteMessage, version: Version) {
        buf.writeList(registries) { registry ->
            buf.writeString(registry.registryId)
            buf.writeList(registry.tags) { tag ->
                buf.writeString(tag.name)
                buf.writeVarInt(tag.entryIds.size)
                for (id in tag.entryIds) buf.writeVarInt(id)
            }
        }
    }
}

/** A data pack both sides may already have, e.g. `minecraft:core` at version "26.3". */
data class KnownPack(val namespace: String, val id: String, val version: String)

/**
 * Select Known Packs (1.20.5+): offers packs the client may have built in. For registry entries
 * from a pack the client confirms, Registry Data can omit the entry's data and the client loads its
 * own copy — so registry *contents* never need to match the client's version exactly.
 */
class SelectKnownPacksPacket(val packs: List<KnownPack>) : ClientboundPacket {
    override fun encode(buf: ByteMessage, version: Version) = buf.writeList(packs) {
        buf.writeString(it.namespace)
        buf.writeString(it.id)
        buf.writeString(it.version)
    }
}

class FinishConfigurationAckPacket : ServerboundPacket

/** The client's reply to [SelectKnownPacksPacket]: the offered packs it actually has. */
class KnownPacksResponsePacket(val packs: List<KnownPack>) : ServerboundPacket
class ConfigKeepAliveResponsePacket(val id: Long) : ServerboundPacket

object ConfigurationPackets {
    fun register(reg: StateRegistry) {
        reg.clientbound<FinishConfigurationPacket>(
            "finish_configuration",
            PacketMapping.ofProtocol(764 to 0x02, 766 to 0x03),
        )
        reg.clientbound<ConfigDisconnectPacket>(
            "disconnect",
            PacketMapping.ofProtocol(764 to 0x01, 766 to 0x02),
        )
        reg.clientbound<ConfigKeepAlivePacket>(
            "keep_alive",
            PacketMapping.ofProtocol(764 to 0x03, 766 to 0x04),
        )
        reg.clientbound<ConfigPluginMessagePacket>(
            "custom_payload",
            PacketMapping.ofProtocol(764 to 0x00, 766 to 0x01),
        )
        reg.clientbound<RegistryDataPacket>(
            "registry_data",
            PacketMapping.ofProtocol(764 to 0x05, 766 to 0x07),
        )
        reg.clientbound<CodecRegistryDataPacket>("registry_data", PacketMapping.ofProtocol(764 to 0x05))
        reg.clientbound<SelectKnownPacksPacket>(
            "select_known_packs",
            PacketMapping.ofProtocol(766 to 0x0e, 777 to 0x0f),
        )
        reg.clientbound<UpdateTagsPacket>(
            "tags",
            PacketMapping.ofProtocol(764 to 0x08, 765 to 0x09, 766 to 0x0d, 777 to 0x0e),
        )

        reg.serverbound("finish_configuration", PacketMapping.ofProtocol(764 to 0x02, 766 to 0x03)) { _, _ ->
            FinishConfigurationAckPacket()
        }
        reg.serverbound("keep_alive", PacketMapping.ofProtocol(764 to 0x03, 766 to 0x04)) { buf, _ ->
            ConfigKeepAliveResponsePacket(buf.buf.readLong())
        }
        reg.serverbound("select_known_packs", PacketMapping.ofProtocol(766 to 0x07)) { buf, _ ->
            KnownPacksResponsePacket(buf.readList { KnownPack(buf.readString(), buf.readString(), buf.readString()) })
        }
    }
}
